import type {
  Activity,
  ActivityType,
  Assessment,
  ContentBundle,
  Module,
  Resource,
} from '@repair/content-schema';
import { TIER_LABELS } from '@repair/content-schema';

// Generated by `pnpm content:build` from /content. Do not edit by hand.
import raw from './content.generated.json';

// The checked-in bundle can lag behind the authored files. Keep these safety
// corrections in effect until it is deliberately regenerated and reviewed.
const bundle = raw as unknown as ContentBundle;

/** Keep activity-specific guidance, adding only common cautions not already in it. */
function standardAssessmentIntro(intro: string): string {
  const additions: string[] = [];
  if (!/\bnot\b[^.]*\bdiagnos/i.test(intro)) {
    additions.push('This draft is for reflection, not diagnosis.');
  }
  if (!/\bunvalidated\b|\bnot\b[^.]*\bvalidated\b/i.test(intro)) {
    additions.push('Scores and thresholds have not been validated.');
  }
  if (!/\bunencrypted\b|\bwithout (?:an app lock or )?encryption\b/i.test(intro)) {
    additions.push('Results are stored unencrypted.');
  }
  additions.push('There are no separate partner accounts or partner sharing.');
  return [intro, ...additions].join('\n\n');
}

export const content: ContentBundle = {
  ...bundle,
  activities: bundle.activities.map((activity) => {
    if (activity.type !== 'assessment') return activity;
    if (activity.kind === 'safety') return {
      ...activity,
      items: activity.items.map((item) => item.id === 'q2' ? { ...item, flagAtOrAbove: 1 } : item),
    };
    return {
      ...activity,
      intro: standardAssessmentIntro(activity.intro),
    };
  }),
};
export { TIER_LABELS };

const activityById = new Map(content.activities.map((a) => [a.id, a]));
const moduleBySlug = new Map(content.modules.map((m) => [m.slug, m]));

export const getModule = (slug: string): Module | undefined => moduleBySlug.get(slug);
export const getActivity = (id: string): Activity | undefined => activityById.get(id);

export function activitiesFor(moduleSlug: string, type?: ActivityType): Activity[] {
  return content.activities.filter((a) => a.module === moduleSlug && (!type || a.type === type));
}

/** Show unfilled outline entries even when some activities of the type exist. */
export function outlinePlanned(outline: Module['outline'], type: ActivityType, authored: Activity[]): string[] {
  const entries: Record<ActivityType, string[]> = {
    assessment: [outline.assessment],
    lesson: outline.lessons,
    exercise: outline.exercises,
    conversation: outline.conversations,
    journal: outline.journal ? [outline.journal] : [],
    ritual: outline.ritual ? [outline.ritual] : [],
  };
  const normalize = (s: string) => s.trim().replace(/\s+/g, ' ').toLowerCase();
  const titles = new Set(authored.filter((a) => a.type === type).map((a) => normalize(a.title)));
  return entries[type].filter((title) => !titles.has(normalize(title)));
}

function globalAssessment(kind: 'onboarding' | 'safety'): Assessment {
  const found = content.activities.find((a) => a.type === 'assessment' && a.kind === kind);
  if (!found || found.type !== 'assessment') throw new Error(`content bundle has no ${kind} assessment`);
  return found;
}

export const onboardingAssessment = globalAssessment('onboarding');
export const safetyScreen = globalAssessment('safety');
export const weeklyConversationId = content.checkins.weekly.conversation;

export const resources = (category?: Resource['category']) =>
  content.resources.filter((r) => !category || r.category === category);

/** Modules hidden for a user whose private safety mode is on. */
export const hiddenInSafetyMode = content.modules
  .filter((m) => m.gating.hiddenInSafetyMode)
  .map((m) => m.slug);

export const TYPE_LABELS: Record<ActivityType, string> = {
  assessment: 'Assessment',
  lesson: 'Lesson',
  exercise: 'Exercise',
  conversation: 'Conversation',
  journal: 'Journal',
  ritual: 'Ritual',
};

/** Default deny: even solo/either material can be harmful during coercion.
 * The unvalidated safety check is the sole development-preview exception. */
export const isHiddenForSafety = (a: Activity) => a.id !== safetyScreen.id;
